      // Let browser handle scroll restoration naturally
      if ('scrollRestoration' in history) {
        history.scrollRestoration = 'auto';
      }

      // Function to clear scroll position for destination URL
      function clearScrollPosition(destinationUrl) {
        const scrollPositions = JSON.parse(localStorage.getItem('scrollPositions') || '{}');

        // Clear scroll position for the destination page
        if (scrollPositions[destinationUrl]) {
          delete scrollPositions[destinationUrl];
          localStorage.setItem('scrollPositions', JSON.stringify(scrollPositions));
        }
      }

      // Wait for DOM to be ready before adding event listeners
      function addMenuListeners() {
        // Add click listener for navigation menu items
        document.addEventListener('click', function(event) {
          // Check for both drawer menu items and header menu items
          const drawerMenuItem = event.target.closest('.menu-drawer__menu-item');
          const headerMenuItem = event.target.closest('.mega-menu__link');
          const menuItem = drawerMenuItem || headerMenuItem;

          if (menuItem) {
            // Check if the menu item itself is an <a> element with href
            if (menuItem.tagName === 'A' && menuItem.href) {
              clearScrollPosition(menuItem.href);
            }
          }
        });

        // Add keydown listener for navigation menu items (accessibility)
        document.addEventListener('keydown', function(event) {
          const drawerMenuItem = event.target.closest('.menu-drawer__menu-item');
          const headerMenuItem = event.target.closest('.mega-menu__link');
          const menuItem = drawerMenuItem || headerMenuItem;

          if (menuItem && (event.key === 'Enter' || event.key === ' ')) {
            // Check if the menu item itself is an <a> element with href
            if (menuItem.tagName === 'A' && menuItem.href) {
              clearScrollPosition(menuItem.href);
            }
          }
        });
      }

      // Add listeners when DOM is ready
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', addMenuListeners);
      } else {
        addMenuListeners();
      }
    </script>

